 static void styleSeek(Activity a,SeekBar seek){boolean dragging=Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"dragging"));String want=dragging?"mp-seek-drag":"mp-seek";if(want.equals(String.valueOf(seek.getTag()))&&seek.getProgressDrawable() instanceof LayerDrawable)return;seek.setTag(want);int track=Math.max(2,dp(a,dragging?PlayerLayoutMetrics.SEEK_DRAG_DP:PlayerLayoutMetrics.SEEK_DP)),box=dp(a,24),inset=Math.max(0,(box-track)/2),thumbPx=dp(a,PlayerLayoutMetrics.THUMB_DP);GradientDrawable bg=trackDrawable(0x33ffffff,track),buf=trackDrawable(0x66ffffff,track),fg=trackDrawable(0xffffffff,track);ClipDrawable bufClip=new ClipDrawable(buf,Gravity.START,ClipDrawable.HORIZONTAL),fgClip=new ClipDrawable(fg,Gravity.START,ClipDrawable.HORIZONTAL);LayerDrawable layer=new LayerDrawable(new Drawable[]{bg,bufClip,fgClip});layer.setId(0,android.R.id.background);layer.setId(1,android.R.id.secondaryProgress);layer.setId(2,android.R.id.progress);layer.setLayerInset(0,0,inset,0,inset);layer.setLayerInset(1,0,inset,0,inset);layer.setLayerInset(2,0,inset,0,inset);seek.setProgressDrawable(layer);seek.setProgressTintList(null);seek.setProgressBackgroundTintList(null);seek.setSecondaryProgressTintList(null);seek.setThumbTintList(null);GradientDrawable thumb=new GradientDrawable();thumb.setShape(GradientDrawable.OVAL);thumb.setColor(0xffffffff);thumb.setSize(thumbPx,thumbPx);seek.setThumb(thumb);seek.setSplitTrack(false);seek.setThumbOffset(thumbPx/2);seek.setMinimumHeight(box);seek.setPadding(thumbPx/2,0,thumbPx/2,0);}
