 static void save(Activity a,Bitmap bitmap){try{String name="suiying-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.US).format(new Date())+".jpg";android.content.ContentValues values=new android.content.ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,name);values.put(MediaStore.Images.Media.MIME_TYPE,"image/jpeg");if(Build.VERSION.SDK_INT>=29)values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/随影");android.net.Uri uri=a.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new java.io.IOException("empty");try(OutputStream out=a.getContentResolver().openOutputStream(uri)){if(out==null||!bitmap.compress(Bitmap.CompressFormat.JPEG,90,out))throw new java.io.IOException("write");}toast(a,"已保存到相册");}catch(Exception e){try{java.io.File dir=a.getExternalFilesDir(android.os.Environment.DIRECTORY_PICTURES);if(dir==null)dir=a.getCacheDir();dir.mkdirs();java.io.File file=new java.io.File(dir,"suiying-"+System.currentTimeMillis()+".jpg");try(java.io.FileOutputStream out=new java.io.FileOutputStream(file)){bitmap.compress(Bitmap.CompressFormat.JPEG,90,out);}toast(a,"已保存截图");}catch(Exception again){toast(a,"截图保存失败");}}finally{bitmap.recycle();}}
